entries[86213] = { ["name"] = "Seelentausch: Einhauchen", ["text"] = "6% von Grundmana 40 Meter Reichweite\nSofort\nIhr kopiert alle regelmäßigen Schattenschadenseffekte auf Eurem Ziel mit gleicher Dauer und Macht.\n\nInnerhalb von 3 Sek. wird das nächste Ziel, auf das Ihr 'Seelentausch: Einhauchen' wirkt, mit den kopierten regelmäßigen Schattenschadenseffekten belegt.\n\n'Seelentausch' kann nicht zweimal hintereinander auf das gleiche Ziel gewirkt werden. [ Seelenbrand : Seelenbrand:\nBelegt das Ziel mit 'Verderbnis', 'Instabiles Gebrechen' und 'Agonie', ohne dass diese Effekte vom Ursprungsziel entfernt werden. ]" }
