entries[86641] = { ["name"] = "Handbuch der Dungeonerkundung", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament (10), Infernotinte (8), Flüchtiges Leben (24), Flüchtiges Wasser (6)\nHandbuch der Dungeonerkundung\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+252 Ausdauer\n+168 Intelligenz\nErhöht Eure Trefferwertung um + 116.\nErhöht Eure Meisterschaftswertung um + 107.\n85" }
