entries[86644] = { ["name"] = "Origamischlamm", ["text"] = "Wirken in 3 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament (3)\nDiese besondere Kreation benötigt eine Menge klatschnasses Pergament und Tinte.\nBenutzen: Setzt einige kleine, tintengetränkte Schlamme am Boden ab. (10 Sek. Abklingzeit)" }
