entries[86648] = { ["name"] = "Schlüssel zu den Ebenen", ["text"] = "Wirken in 3 sek. 5\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament (10), Infernotinte (2), Flüchtiges Wasser (2), Flüchtige Luft (2), Flüchtige Erde (2)\nSchlüssel zu den Ebenen\nWird beim Anlegen gebunden\nZweihändig Stab\n2,204 - 3,307 Schaden Tempo 3.30\n(835.00 Schaden pro Sekunde)\n+343 Ausdauer\n+229 Intelligenz\nErhöht Eure Trefferwertung um + 153.\nErhöht Eure Tempowertung um + 153.\nErhöht die Zaubermacht um + 1.310.\nHaltbarkeit 100 / 100\n81" }
