entries[86698] = { ["name"] = "Wächter der Uralten Könige", ["text"] = "30 Meter Reichweite\nSofort 3 min Abklingzeit\nBeschwört einen Wächter der Uralten Könige, der Euch 30 Sek. lang im Kampf unterstützt.\n\nDer Wächter der Uralten Könige wird Euer aktuelles Ziel angreifen. Sowohl Eure Angriffe als auch die des Wächters werden Euch mit Uralter Kraft erfüllen, die als 'Uralter Furor' entfesselt wird, wenn der Wächter seinen Abschied nimmt." }
